import{_ as r,l,o as e,c as n,v as t,p as s,x as o,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"资本管制","description":"","frontmatter":{"title":"资本管制","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/capital-controls.md","filePath":"econ/capital-controls.md","lastUpdated":1789023840000}'),c={name:"econ/capital-controls.md"};function A(B,a,h,_,u,f){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="资本管制" tabindex="-1">资本管制 <a class="header-anchor" href="#资本管制" aria-label="Permalink to &quot;资本管制&quot;">​</a></h1><div class="epigraph"><p>三角的第三角：用管制换取钉住加一点货币空间；宏观审慎时代把它从禁忌改写成工具，但规避、配置扭曲与信号成本没有消失。</p><footer>—— 据 Magud, Reinhart and Rogoff 管制效力综述；Ostry 等 IMF 审慎框架；Klein 墙与门</footer></div><p><a href="/econ/crisis-generations">上一课</a>把危机分代。本课缺口是政策：资本管制。主权财富基金下一课换官方的资产侧；本课钉管制在三角、危机与宏观审慎里的位置，不重写<a href="/econ/impossible-trinity">不可能三角</a>全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开放资本时，钉住吃掉货币独立。管制提高套利成本，使 \\(i\\) 可以暂时离开 \\(i^*+\\mathbb{E}\\Delta e\\)。流入管制（准备金、税、审批）针对过热与货币升值；流出管制针对储备漏出与停止。缺口是效力：规避（假贸易、内部定价、衍生品）使法定管制不等于事实封闭。Klein：墙上的砖（长期封闭）与门（危机时开关）效果不同；门的信号可以加速流出。</p><p><span class="marginnote">智利 URR、马来西亚 1998、冰岛危机后、近年新兴宏观审慎，是经验菜单。本课机制，不评分某国「成功」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把管制写成 \\(\\tau\\) 进资本账户，类似贸易冰山。第一代：降低漏出速度，推迟 \\(T\\)，不改信贷规则则仍破。第二代：提高攻击成本，可移出灰色区。第三代：紧急闸减少火线出售的跨境腿。代价：配置（Lucas 的 \\(K\\) 更不流）、规避成本、治理寻租。IMF 后 2008 的制度观点：流入管制可当审慎，不是绝对禁忌，但仍次于国内审慎若后者可用。</p>',8)),(e(),s(d,null,{default:o(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRI%5B%22%E4%B8%89%E8%A7%92%E7%AC%AC%E4%B8%89%E8%A7%92%22%5D%20--%3E%20SPACE%5B%22%E9%92%89%E4%BD%8F%20%2B%20%E4%B8%80%E7%82%B9%20i%20%E7%A9%BA%E9%97%B4%22%5D%0A%20%20IN%5B%22%E6%B5%81%E5%85%A5%E7%AE%A1%E5%88%B6%22%5D%20--%3E%20HEAT%5B%22%E9%99%8D%E6%B8%A9%20%2F%20%E5%B0%91%E5%8D%87%E5%80%BC%22%5D%0A%20%20OUT%5B%22%E6%B5%81%E5%87%BA%E7%AE%A1%E5%88%B6%22%5D%20--%3E%20T%5B%22%E6%8E%A8%E8%BF%9F%E5%82%A8%E5%A4%87%E8%80%97%E5%B0%BD%22%5D%0A%20%20EVA%5B%22%E8%A7%84%E9%81%BF%22%5D%20--%3E%20GAP%5B%22%E6%B3%95%E5%AE%9A%20%E2%89%A0%20%E4%BA%8B%E5%AE%9E%22%5D%0A%20%20DOOR%5B%22%E5%8D%B1%E6%9C%BA%E6%97%B6%E5%85%B3%E9%97%A8%22%5D%20--%3E%20SIG%5B%22%E4%BF%A1%E5%8F%B7%3A%20%E5%8F%AF%E8%83%BD%E5%8A%A0%E9%80%9F%E8%B7%91%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与贸易协定：货物 GATT 没有同等的资本账户多边约束（IMF 第八条管经常兑换）。资本开放是单边 / 双边选择，政治经济不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是楔子。楔子创造空间也创造寻租。宏观审慎（LTV、外汇贷款限制）可以是「谁借」的管制，比全面外汇管制更准，仍是资本账户的亲戚。储备干预是价格与数量的另一只手：管制与干预常一起用（怕浮动的完整工具箱）。</p><p>与 FH / Lucas：长期墙降低跨境净流，可以抬高 FH 的 \\(\\beta\\)、加重 Lucas 缺失。短期门改变危机动力学，不改变稳态 \\(A\\)。</p><p><span class="marginnote">Magud–Reinhart–Rogoff：流入管制对组成（从短债转向更长）比对总量更有证据；对汇率与利率的效果较弱、较短。效力陈述必须说对象。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供如何设计规避的任何说明。不把管制写成免费的第三顶点——三角仍在，只是「开放」变成有弹性。下一课主权财富基金：管制与储备的镜像是官方把顺差变成海外资产组合。不要用管制课重写贸易关税；对象是资产流。</p><p>后课默认：管制是三角第三角与危机闸，效力被规避打折；门与墙不同。审慎可以替代部分全面管制。信贷规则不改，第一代 \\(T\\) 只是推迟。SWF 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>管制用楔子换货币空间，法定开放度 ≠ 事实。</li><li>流入：组成往往比总量更听使唤；流出闸有信号风险。</li><li>对三代危机分别是推迟、加成本、紧急闸。</li><li>宏观审慎是更定向的亲戚，不是取消三角。</li><li>出处：Magud, Reinhart and Rogoff；Klein；Ostry 等 IMF 研究。</li></ul>',10))])}const D=r(c,[["render",A]]);export{T as __pageData,D as default};
